from tastypie.resources import ModelResource
from tastypie.authentication import ApiKeyAuthentication
from tastypie.exceptions import NotFound, Unauthorized
from .models import CloudBackupSnapshot

class BackupSnapshotResource(ModelResource):
    class Meta:
        queryset = CloudBackupSnapshot.objects.all()
        resource_name = 'backups'
        authentication = ApiKeyAuthentication()

    def obj_delete(self, bundle, **kwargs):
        try:
            snapshot = CloudBackupSnapshot.objects.get(pk=kwargs['pk'])
        except CloudBackupSnapshot.DoesNotExist:
            raise NotFound('Snapshot not found')

        # Ensure the backup belongs to the authenticated user's tenant
        if snapshot.tenant != bundle.request.user.tenant:
            raise Unauthorized('Access denied: snapshot belongs to another tenant')

        snapshot.delete()
